import{z as A,x as d,o as r,c as B,q as n,j as s,D as e,d as l,s as o,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const V=JSON.parse('{"title":"Bellman–Ford","description":"","frontmatter":{"title":"Bellman–Ford","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bellman-ford.md","filePath":"cs/bellman-ford.md","lastUpdated":1791413859000}'),p={name:"cs/bellman-ford.md"};function m(C,a,D,f,h,F){const t=d("Mermaid");return r(),B("div",null,[a[2]||(a[2]=n('<h1 id="bellman–ford" tabindex="-1">Bellman–Ford <a class="header-anchor" href="#bellman–ford" aria-label="Permalink to &quot;Bellman–Ford&quot;">​</a></h1><div class="epigraph"><p>允许负边时，反复把每条边松弛 $|V|-1$ 遍；还能再松弛，就有从源可达的负环。</p><footer>—— 据 Bellman, On a Routing Problem, 1958；Ford, 1956；CLRS 第 24 章整理</footer></div><p>上一课<a href="/cs/dijkstra-heap">Dial 与堆变体</a>在非负权上钉死 Extract-Min。本课不重证那条不变式。缺口是：<strong>边权可为负</strong>，但不能让「越走越短」的负环把最短路定义毁掉。本课交出 \\(|V|-1\\) 轮全边松弛，以及第 \\(|V|\\) 轮检测。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最短路若存在，简单路径最多 \\(|V|-1\\) 条边。对每条边松弛一轮，至多把「边数 \\(\\le k\\) 的最短路」推进到 \\(k+1\\)。故 \\(|V|-1\\) 轮后，若无负环可达，则 \\(d[v]=\\delta(s,v)\\)。再松弛成功则存在从 \\(s\\) 可达的负环，最短路无下界。</p><p>Dijkstra 的 \\(S\\) 在负边下会过早钉死。本课不用优先队列，每轮扫全部边。代价 \\(O(VE)\\)。仍在 P；不引入 NP。</p><h3 id="负环不是「有负边」" tabindex="-1">负环不是「有负边」 <a class="header-anchor" href="#负环不是「有负边」" aria-label="Permalink to &quot;负环不是「有负边」&quot;">​</a></h3><p>负边可以出现在 DAG 或正环图上，最短路仍在。只有<strong>环上权和为负</strong>且从源可达才使 \\(\\delta=-\\infty\\)。不可达的负环不妨碍源点树。检测只对还能松弛的点及其前驱链负责。</p><p><span class="marginnote">常见误区：看到负边就以为最短路没法算了。实际上只要负边不凑成从源可达的负环，距离照样收敛、答案照样有限；坏掉的只是 Dijkstra 那套「取出即定死」的贪心，所以这里改用笨办法反复扫全部边。</span></p><p><span class="marginnote">Bellman 1958 与 Ford 的标号法是同一松弛。CLRS 24.1 把第 \\(n\\) 轮当检测。路由里的距离向量是后话；本课只在静态图上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>初始化同 Dijkstra。重复 \\(|V|-1\\) 次：对 \\(E\\) 中每条边松弛。再扫一遍，若仍更新则报负环。前驱链可回溯环，本课不写找环的细节。</p><p><span class="marginnote">术语翻译：松弛就是「试一次绕行」——检查经由边 \\((u,v)\\) 走到 \\(v\\)，是否比 \\(v\\) 当前记录的距离更近，是就改写。可以想象成导航软件每次发现更快的路线就更新预计到达时间；扫完全部边，就是把每个路口的绕行方案都问一遍。</span></p>',13)),(r(),s(i,null,{default:e(()=>[o(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20INIT%5B%22d%5Bs%5D%3D0%22%5D%20--%3E%20R%5B%22%E6%9D%BE%E5%BC%9B%E5%85%A8%E9%83%A8%E8%BE%B9%EF%BC%8C%7CV%7C-1%20%E8%BD%AE%22%5D%0A%20%20R%20--%3E%20TEST%5B%22%E5%86%8D%E6%9D%BE%E5%BC%9B%EF%BC%9F%22%5D%0A%20%20TEST%20--%3E%7C%22%E5%90%A6%22%7C%20OK%5B%22d%20%3D%20%CE%B4%22%5D%0A%20%20TEST%20--%3E%7C%22%E6%98%AF%22%7C%20NEG%5B%22%E5%8F%AF%E8%BE%BE%E8%B4%9F%E7%8E%AF%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("a",{href:"/cs/adj-list-matrix"},"邻接表"),l("每轮扫 \\(E\\)。稀疏图仍是 \\(O(VE)\\)，没有 Dijkstra 那种堆加速——负权禁止那个贪心。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"\\(k\\) 轮后不变式：若 \\(\\delta(s,v)\\) 有限且某最短路 \\(\\le k\\) 条边，则 \\(d[v]\\) 已正确。负环打断「简单最短路」的存在。差分约束系统可化成本课：边权为不等式，负环即不可行，本课点名不展开。",-1)),a[6]||(a[6]=E("p",null,"为什么恰好 \\(|V|-1\\) 轮：正确性沿「边数」逐轮推进，每轮把能确定的最短路多延长一条边。",-1)),(r(),s(i,null,{default:e(()=>[o(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20K0%5B%22%E7%AC%AC%200%20%E8%BD%AE%EF%BC%9A%E5%8F%AA%E6%9C%89%20d%5Bs%5D%20%E5%AE%9A%E6%A1%88%5D%20--%3E%20K1%5B%E7%AC%AC%201%20%E8%BD%AE%EF%BC%9A%E8%BE%B9%E6%95%B0%20%E2%89%A41%20%E7%9A%84%E6%9C%80%E7%9F%AD%E8%B7%AF%E5%AE%9A%E6%A1%88%22%5D%0A%20%20K1%20--%3E%20K2%5B%22%E7%AC%AC%202%20%E8%BD%AE%EF%BC%9A%E8%BE%B9%E6%95%B0%20%E2%89%A42%20%E5%AE%9A%E6%A1%88%22%5D%0A%20%20K2%20--%3E%20KM%5B%22%E7%AC%AC%20k%20%E8%BD%AE%EF%BC%9A%E8%BE%B9%E6%95%B0%20%E2%89%A4k%20%E5%AE%9A%E6%A1%88%22%5D%0A%20%20KM%20--%3E%20KV%5B%22%E7%AC%AC%20%7CV%7C-1%20%E8%BD%AE%EF%BC%9A%E5%85%A8%E9%83%A8%E7%AE%80%E5%8D%95%E6%9C%80%E7%9F%AD%E8%B7%AF%E5%AE%9A%E6%A1%88%22%5D%0A%20%20KV%20--%3E%20X%5B%22%E7%AC%AC%20%7CV%7C%20%E8%BD%AE%E4%BB%8D%E8%83%BD%E6%9B%B4%E6%96%B0%20%E2%86%92%20%E5%8F%AF%E8%BE%BE%E8%B4%9F%E7%8E%AF%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">数字实例：\\(|V|=5\\) 时简单路径最多 \\(4\\) 条边，故 \\(4\\) 轮后所有无负环的 \\(d\\) 值必须到位；若第 \\(5\\) 轮还能把某个 \\(d\\) 再减小，说明有路径在环上反复「回血」变短，这正是负环的签名。</span></p><p>与拓扑：DAG 上按拓扑一轮松弛即可，不必 \\(|V|-1\\) 轮。有环才需要本课的重复。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做全源（可对每个源跑，或后课 Floyd）。不处理费用流。浮点误差可把「近零负环」判错，实现用整数权。也不把「SPFA 队列优化」当最坏保证：最坏仍可 \\(VE\\) 量级。</p><p>后课默认：负边单源 = Bellman–Ford，\\(O(VE)\\)，可检测可达负环。全源后课用三维 DP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(|V|-1\\) 轮全边松弛给出无负环时的单源最短路。</li><li>第 \\(|V|\\) 轮还能松弛 \\(\\Leftrightarrow\\) 可达负环。</li><li>代价 \\(O(VE)\\)；不能用 Dijkstra 的取出。</li><li>出处：Bellman, 1958；CLRS 第 24.1 节。</li></ul>',7))])}const c=A(p,[["render",m]]);export{V as __pageData,c as default};
